}

/**
 * @suppress
 */
public object FfiConverterBoolean: FfiConverter<Boolean, Byte> {
    override fun lift(value: Byte): Boolean {
        return value.toInt() != 0
    }

    override fun read(buf: ByteBuffer): Boolean {
        return lift(buf.get())
    }

    override fun lower(value: Boolean): Byte {
        return if (value) 1.toByte() else 0.toByte()
    }

    override fun allocationSize(value: Boolean) = 1UL

    override fun write(value: Boolean, buf: ByteBuffer) {
        buf.put(lower(value))
    }
}

/**
 * @suppress
 */
public object FfiConverterString: FfiConverter<String, RustBuffer.ByValue> {
    // Note: we don't inherit from FfiConverterRustBuffer, because we use a
    // special encoding when lowering/lifting.  We can use `RustBuffer.len` to
    // store our length and avoid writing it out to the buffer.
    override fun lift(value: RustBuffer.ByValue): String {
        try {
            val byteArr = ByteArray(value.len.toInt())
            value.asByteBuffer()!!.get(byteArr)
            return byteArr.toString(Charsets.UTF_8)
        } finally {
            RustBuffer.free(value)
        }
    }

    override fun read(buf: ByteBuffer): String {
        val len = buf.getInt()
        val byteArr = ByteArray(len)
        buf.get(byteArr)
        return byteArr.toString(Charsets.UTF_8)
    }

    fun toUtf8(value: String): ByteBuffer {
        // Make sure we don't have invalid UTF-16, check for lone surrogates.
        return Charsets.UTF_8.newEncoder().run {
            onMalformedInput(CodingErrorAction.REPORT)
            encode(CharBuffer.wrap(value))
        }
    }

    override fun lower(value: String): RustBuffer.ByValue {
        val byteBuf = toUtf8(value)
        // Ideally we'd pass these bytes to `ffi_bytebuffer_from_bytes`, but doing so would require us
        // to copy them into a JNA `Memory`. So we might as well directly copy them into a `RustBuffer`.
        val rbuf = RustBuffer.alloc(byteBuf.limit().toULong())
        rbuf.asByteBuffer()!!.put(byteBuf)
        return rbuf
    }

    // We aren't sure exactly how many bytes our string will be once it's UTF-8
    // encoded.  Allocate 3 bytes per UTF-16 code unit which will always be
    // enough.
    override fun allocationSize(value: String): ULong {
        val sizeForLength = 4UL
        val sizeForString = value.length.toULong() * 3UL
        return sizeForLength + sizeForString
    }

    override fun write(value: String, buf: ByteBuffer) {
        val byteBuf = toUtf8(value)
        buf.putInt(byteBuf.limit())
        buf.put(byteBuf)
    }
}

/**
 * @suppress
 */
public object FfiConverterByteArray: FfiConverterRustBuffer<ByteArray> {
    override fun read(buf: ByteBuffer): ByteArray {
        val len = buf.getInt()
        val byteArr = ByteArray(len)
        buf.get(byteArr)
        return byteArr
    }
    override fun allocationSize(value: ByteArray): ULong {
        return 4UL + value.size.toULong()
    }
    override fun write(value: ByteArray, buf: ByteBuffer) {
        buf.putInt(value.size)
        buf.put(value)
    }
}



/**
 * Statistics from one disclosed carrier detector.
 */
data class AnalysisReport (
    var `carrier`: CarrierChoice,
    var `symbols`: kotlin.ULong,
    var `visibleScalars`: kotlin.ULong,
    var `density`: kotlin.Double,
    var `chiSquare`: kotlin.Double,
    var `longestRun`: kotlin.ULong,
    var `meanGap`: kotlin.Double,
    var `gapCoefficientOfVariation`: kotlin.Double,
    var `positionalEntropy`: kotlin.Double,
    var `suspicionScore`: kotlin.UByte,
    var `likelyDetectable`: kotlin.Boolean
) {

    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAnalysisReport: FfiConverterRustBuffer<AnalysisReport> {
    override fun read(buf: ByteBuffer): AnalysisReport {
        return AnalysisReport(
            FfiConverterTypeCarrierChoice.read(buf),
            FfiConverterULong.read(buf),
            FfiConverterULong.read(buf),
            FfiConverterDouble.read(buf),
            FfiConverterDouble.read(buf),
            FfiConverterULong.read(buf),
            FfiConverterDouble.read(buf),
            FfiConverterDouble.read(buf),
            FfiConverterDouble.read(buf),
            FfiConverterUByte.read(buf),
            FfiConverterBoolean.read(buf),
        )
    }

    override fun allocationSize(value: AnalysisReport) = (
            FfiConverterTypeCarrierChoice.allocationSize(value.`carrier`) +
            FfiConverterULong.allocationSize(value.`symbols`) +
            FfiConverterULong.allocationSize(value.`visibleScalars`) +
            FfiConverterDouble.allocationSize(value.`density`) +
            FfiConverterDouble.allocationSize(value.`chiSquare`) +
            FfiConverterULong.allocationSize(value.`longestRun`) +
            FfiConverterDouble.allocationSize(value.`meanGap`) +
            FfiConverterDouble.allocationSize(value.`gapCoefficientOfVariation`) +
            FfiConverterDouble.allocationSize(value.`positionalEntropy`) +
            FfiConverterUByte.allocationSize(value.`suspicionScore`) +
            FfiConverterBoolean.allocationSize(value.`likelyDetectable`)
    )

    override fun write(value: AnalysisReport, buf: ByteBuffer) {
            FfiConverterTypeCarrierChoice.write(value.`carrier`, buf)
            FfiConverterULong.write(value.`symbols`, buf)
            FfiConverterULong.write(value.`visibleScalars`, buf)
            FfiConverterDouble.write(value.`density`, buf)
            FfiConverterDouble.write(value.`chiSquare`, buf)
            FfiConverterULong.write(value.`longestRun`, buf)
            FfiConverterDouble.write(value.`meanGap`, buf)
            FfiConverterDouble.write(value.`gapCoefficientOfVariation`, buf)
            FfiConverterDouble.write(value.`positionalEntropy`, buf)
            FfiConverterUByte.write(value.`suspicionScore`, buf)
            FfiConverterBoolean.write(value.`likelyDetectable`, buf)
    }
}



/**
 * Hard payload ceiling and carrier expansion at that ceiling.
 */
data class CapacityReport (
    var `maxPayloadBytes`: kotlin.ULong,
    var `containerBytesAtLimit`: kotlin.ULong,
    var `carrierSymbolsAtLimit`: kotlin.ULong
) {

    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeCapacityReport: FfiConverterRustBuffer<CapacityReport> {
    override fun read(buf: ByteBuffer): CapacityReport {
        return CapacityReport(
            FfiConverterULong.read(buf),
            FfiConverterULong.read(buf),
            FfiConverterULong.read(buf),
        )
    }

    override fun allocationSize(value: CapacityReport) = (
            FfiConverterULong.allocationSize(value.`maxPayloadBytes`) +
            FfiConverterULong.allocationSize(value.`containerBytesAtLimit`) +
            FfiConverterULong.allocationSize(value.`carrierSymbolsAtLimit`)
    )

    override fun write(value: CapacityReport, buf: ByteBuffer) {
            FfiConverterULong.write(value.`maxPayloadBytes`, buf)
            FfiConverterULong.write(value.`containerBytesAtLimit`, buf)
            FfiConverterULong.write(value.`carrierSymbolsAtLimit`, buf)
    }
}



