/**
 * Carrier alphabets supported by wire v4.
 */

enum class CarrierChoice {

    ZERO_WIDTH,
    ZERO_WIDTH_COMPAT,
    VARIATION_SELECTORS,
    UNICODE_TAGS;
    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeCarrierChoice: FfiConverterRustBuffer<CarrierChoice> {
    override fun read(buf: ByteBuffer) = try {
        CarrierChoice.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: CarrierChoice) = 4UL

    override fun write(value: CarrierChoice, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





