/**
 * Stable error boundary for Kotlin and Swift callers.
 */
sealed class SayehFfiException: kotlin.Exception() {

    class Failure(

        val `reason`: kotlin.String
        ) : SayehFfiException() {
        override val message
            get() = "reason=${ `reason` }"
    }


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<SayehFfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): SayehFfiException = FfiConverterTypeSayehFfiError.lift(error_buf)
    }


}

/**
 * @suppress
 */
public object FfiConverterTypeSayehFfiError : FfiConverterRustBuffer<SayehFfiException> {
    override fun read(buf: ByteBuffer): SayehFfiException {


        return when(buf.getInt()) {
            1 -> SayehFfiException.Failure(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: SayehFfiException): ULong {
        return when(value) {
            is SayehFfiException.Failure -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: SayehFfiException, buf: ByteBuffer) {
        when(value) {
            is SayehFfiException.Failure -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalUByte: FfiConverterRustBuffer<kotlin.UByte?> {
    override fun read(buf: ByteBuffer): kotlin.UByte? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterUByte.read(buf)
    }

    override fun allocationSize(value: kotlin.UByte?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterUByte.allocationSize(value)
        }
    }

    override fun write(value: kotlin.UByte?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterUByte.write(value, buf)
        }
    }
}




